"""Independent explanations and examples; only the book's mathematical order is used."""

def ex(code, title, question, solution, model):
    return dict(title=title, question=question, solution=solution, verification=code), dict(id=code, **model)

example_models=[]
def examples(*items):
    example_models.extend(model for _,model in items)
    return [item for item,_ in items]

def lesson(key,title,summary,objective,before,ideas,method,mistakes,worked):
    return dict(key=key,id='fp1_induction_'+key,title=title,summary=summary,objective=objective,before=before,ideas=ideas,method=method,mistakes=mistakes,examples=worked)

lessons=[
lesson('sums','Building an induction proof',
 'Connect a verified starting case to every later integer, rather than extrapolating a pattern.',
 'Prove finite-sum identities by a valid base case, hypothesis and forward implication.',
 r'<p>Review <a href="/courses/maths4u-9231-fp1/topics/fp1_series_power_sums">finite sums</a> and polynomial factorisation. You need to distinguish an identity, a conjecture and a conditional statement.</p>',
 r'''<h3>What must travel from one integer to the next?</h3><p>Let P(n) be a precise statement for integers \(n\ge n_0\). Checking P at several values is evidence for a conjecture, not a proof for infinitely many values. Induction needs two logically separate facts:</p>
 <ol><li>P(n₀) is true by a direct calculation.</li><li>For an arbitrary integer \(k\ge n_0\), if P(k) is true, then P(k+1) is true.</li></ol>
 <p>The second fact is a conditional implication: temporarily use P(k), never P(k+1). The starting case then triggers every successive implication. Without a starting case, a perfectly valid implication might never begin.</p>
 <h3>Name the target before doing the algebra</h3><p>For \(S_n=\sum_{r=a}^{n}t_r\), define P(n) as \(S_n=F(n)\), with \(n\ge a\). At n=a the sum has one term. At the next stage, only the new upper term is added:</p>
 \[S_{k+1}=S_k+t_{k+1}=F(k)+t_{k+1}.\]
 <p>Use algebra to reach F(k+1). You may write F(k+1) separately as your target, but cannot assume it equals the new sum. A useful independent check is \(F(k+1)-F(k)=t_{k+1}\), together with the correct starting value.</p>
 <h3>Scope and conclusion</h3><p>State that P(n₀) and the implication prove P(n) for every integer n≥n₀. A start at 3 proves nothing about 1 or 2. A step of two requires a base in each parity class you intend to cover, or a conclusion restricted to one parity. Finite examples can disprove a statement: one counterexample is enough.</p>''',
 r'<ol><li>State P(n) and its integer domain.</li><li>Evaluate both sides at the actual starting index.</li><li>Assume P(k) for one arbitrary admissible k.</li><li>Add the new term and simplify to the exact k+1 target.</li><li>Conclude with the base case, implication and full domain.</li></ol>',
 ['Several successful substitutions do not establish an infinite claim.','Do not assume the target P(k+1) in your working.','The added term is t(k+1), not t(k).','A sum starting at a has one term when n=a.'],
 examples(
 ex('E-S1','1 · A starting index that is not 1',r'<p>Prove \(\sum_{r=3}^{n}(2r+1)=(n+1)^2-9\) for every integer n≥3.</p>',r'<p>Let P(n) be this identity. At n=3 the left side is 7 and the right side is 16−9=7. Assume P(k) for an arbitrary k≥3. Then</p>\[\sum_{r=3}^{k+1}(2r+1)=(k+1)^2-9+2k+3=(k+2)^2-9.\]<p>This is P(k+1). The verified base and implication prove the identity for all integers n≥3.</p>',dict(kind='sum',term='2*r+1',formula='(n+1)**2-9',lower=3)),
 ex('E-S2','2 · Keep the new term visible',r'<p>Prove \(\sum_{r=1}^{n}r(2r+3)=n(n+1)(4n+11)/6\), n≥1.</p>',r'<p>At n=1 both sides equal 5. Assume the identity for k≥1. Adding the new term gives</p>\[\frac{k(k+1)(4k+11)}6+(k+1)(2k+5)=\frac{(k+1)(k+2)(4k+15)}6.\]<p>Since 4k+15=4(k+1)+11, this is exactly the k+1 formula. With the base case, induction proves the stated identity for every integer n≥1.</p>',dict(kind='sum',term='r*(2*r+3)',formula='n*(n+1)*(4*n+11)/6',lower=1)),
 ex('E-S3','3 · A bound needs its own algebraic bridge',r'<p>Prove \(3^n\ge n^2\) for every integer n≥2.</p>',r'<p>At n=2, 9≥4. Assume 3ᵏ≥k² for k≥2. Multiplication by 3 preserves the inequality. Also</p>\[3k^2-(k+1)^2=2(k-2)^2+6(k-2)+3\ge3>0.\]<p>Thus 3ᵏ⁺¹≥3k²≥(k+1)². The base and implication establish the bound for all integers n≥2. Merely replacing k by k+1 in the assumption would not prove this step.</p>',dict(kind='power_bound',base=3,power=2,start=2,decomposition='2*(n-2)**2+6*(n-2)+3')),
 ex('E-S4','4 · Three matches can still conceal a false formula',r'<p>A proposed formula for \(\sum_{r=1}^{n}(2r-1)\) is \(n^2+(n-1)(n-2)(n-3)\). Find the first failure, then prove the correct formula.</p>',r'<p>The extra factor vanishes at 1, 2 and 3. At n=4 the actual sum is 16, but the proposal gives 22. The correct statement is Sₙ=n². Its base n=1 gives 1=1. Assuming Sₖ=k²,</p>\[S_{k+1}=k^2+2k+1=(k+1)^2.\]<p>Hence Sₙ=n² for every integer n≥1 by induction. The counterexample rejects the proposal; the separate induction establishes its replacement.</p>',dict(kind='sum_counterexample',term='2*r-1',formula='n**2',false='n**2+(n-1)*(n-2)*(n-3)',lower=1,first=4))
 )),
lesson('derivatives','Induction through repeated differentiation',
 'Track the derivative order, signs and factorials through an explicit next step.',
 'Prove derivative formulae with the correct order increment and domain.',
 r'<p>Complete <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">the induction framework</a>. Review the product and chain rules, factorials, and derivatives of exponential, rational and trigonometric functions.</p>',
 r'''<h3>The index counts an operation</h3><p>Write \(D^n y=d^ny/dx^n\). For an ordinary nth-derivative formula, differentiate the assumed kth formula once. Keep n fixed while differentiating in x: factorials and powers depending only on k are constants.</p>
 <p>You may start at n=0 if D⁰y means y itself and the proposed formula is defined there. A formula involving (n−1)! usually starts at 1; do not invent (−1)! to force an earlier base.</p>
 <h3>An even-order statement moves by two derivatives</h3><p>If P(n) describes D²ⁿy, then P(k+1) describes D²ᵏ⁺²y. Differentiate the assumed formula twice. A one-derivative step reaches an odd order instead. For a formula repeating every four derivatives, use four derivatives per step.</p>
 <h3>Show the coefficient update</h3><p>A claimed formula is not justified by spotting the first few derivatives. Use the chain rule, signs and factorial relation explicitly; for example \((k+1)k!=(k+1)!\). For a product of a polynomial and an exponential, differentiate both factors and collect the result into the exact proposed next polynomial.</p>
 <p>Retain the x-domain where the original function and all required derivatives exist. State both quantifiers: every allowed derivative index and every x in that domain.</p>''',
 r'<ol><li>Define the derivative-order statement and domain.</li><li>Check the starting derivative directly.</li><li>Assume the exact kth formula.</li><li>Differentiate the number of times that advances the index once.</li><li>Collect coefficients into the k+1 formula and conclude.</li></ol>',
 ['An index increment is not always one differentiation.','The sign from differentiating a reciprocal must be retained.','Treat k as a constant when differentiating in x.','Check that the factorial is defined at the base case.'],
 examples(
 ex('E-D1','1 · A one-derivative bridge',r'<p>Prove \(D^n(e^{5x-1})=5^ne^{5x-1}\) for every integer n≥0 and real x.</p>',r'<p>For n=0 the identity is the original function. Assume the kth formula. Differentiating once, with 5ᵏ constant, gives</p>\[D^{k+1}(e^{5x-1})=5^k\cdot5e^{5x-1}=5^{k+1}e^{5x-1}.\]<p>Therefore the identity holds for all integers n≥0 and all real x by induction.</p>',dict(kind='derivative',function='exp(5*x-1)',formula='5**n*exp(5*x-1)',start=0,order=1)),
 ex('E-D2','2 · A factorial and a chain-rule factor',r'<p>For x&gt;2/3 prove \(D^n(3x-2)^{-1}=(-1)^n n!3^n(3x-2)^{-n-1}\), n≥0.</p>',r'<p>At n=0 the expression is the original function. Suppose the formula holds for k. Differentiate the x-dependent factor:</p>\[D^{k+1}y=(-1)^kk!3^k(-k-1)3(3x-2)^{-k-2}=(-1)^{k+1}(k+1)!3^{k+1}(3x-2)^{-(k+1)-1}.\]<p>This is the required next formula, so induction proves the result for all n≥0 on x&gt;2/3. The excluded pole is never reintroduced.</p>',dict(kind='derivative',function='1/(3*x-2)',formula='(-1)**n*factorial(n)*3**n/(3*x-2)**(n+1)',start=0,order=1)),
 ex('E-D3','3 · Four differentiations advance one index',r'<p>Let \(y=e^x\cos x\). Prove \(D^{4n}y=(-4)^ny\), n≥0.</p>',r'<p>Direct differentiation gives y′=eˣ(cos x−sin x), y″=−2eˣsin x, y‴=−2eˣ(sin x+cos x), and y⁽⁴⁾=−4y. P(0) is y=y. If D⁴ᵏy=(−4)ᵏy, differentiating four times gives</p>\[D^{4k+4}y=(-4)^kD^4y=(-4)^{k+1}y.\]<p>The base and implication establish the formula for every integer n≥0. Differentiating only once would not reach P(k+1).</p>',dict(kind='derivative',function='exp(x)*cos(x)',formula='(-4)**n*exp(x)*cos(x)',start=0,order=4)),
 ex('E-D4','4 · Use both terms of the product rule',r'<p>For \(y=(x-2)e^{2x}\), prove \(D^ny=2^ne^{2x}(x-2+n/2)\), n≥0.</p>',r'<p>The n=0 case is immediate. Assume the kth expression. Differentiating both factors gives</p>\[D^{k+1}y=2^ke^{2x}\bigl(2(x-2+k/2)+1\bigr)=2^{k+1}e^{2x}\bigl(x-2+(k+1)/2\bigr).\]<p>This reaches the exact next formula. Hence it is valid for every integer n≥0 and real x.</p>',dict(kind='derivative',function='(x-2)*exp(2*x)',formula='2**n*exp(2*x)*(x-2+n/2)',start=0,order=1))
 )),
lesson('recurrences','Recursive formulae and invariant bounds',
 'Use the recurrence to carry a formula or an interval forward, with enough initial cases.',
 'Prove explicit sequence formulae and bounds without assuming a denominator sign or a missing initial case.',
 r'<p>Review <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">the forward implication</a>, inequalities and recurrence notation. An invariant interval is an interval the recurrence maps back into itself.</p>',
 r'''<h3>The recurrence supplies the implication</h3><p>For \(u_{n+1}=g(u_n,n)\), substitute the induction hypothesis into g and simplify. Verify the actual first index, which may be 0. An explicit formula guessed from numerical terms still needs this argument.</p>
 <h3>A second-order recurrence needs two starting values</h3><p>If \(u_{n+2}=a u_{n+1}+b u_n\), prove the proposed formula at both 0 and 1. Assume it at k and k+1, then derive it at k+2. Equivalently, induct on the paired statement that both consecutive cases hold. One initial check cannot determine a two-initial-value sequence.</p>
 <h3>Bounds must survive the actual map</h3><p>To prove \(L&lt;u_n&lt;U\), first check the starting value. Assuming both inequalities at k, establish that the next term is defined, then show both new inequalities. In a rational recurrence the denominator's positivity must follow from the assumed interval before an inequality is multiplied through it.</p>
 <p>For a square-root recurrence, check the radicand and the non-negative branch before squaring a proposed bound. A bounded sequence need not converge; a monotone bounded sequence does. If a limit is requested, justify convergence first, then use continuity of the recurrence on its interval and select an admissible fixed point.</p>''',
 r'<ol><li>Record the starting index and all initial values.</li><li>State a formula or invariant interval precisely.</li><li>Check the needed base cases.</li><li>Apply the recurrence to the assumed case(s), justifying domains and signs.</li><li>Conclude induction; prove monotonicity separately if a limit is needed.</li></ol>',
 ['One base case is insufficient for a general second-order recurrence.','Do not reverse the implication by assuming the next formula.','A denominator may change the direction of an inequality.','Boundedness alone does not justify taking a limit.'],
 examples(
 ex('E-R1','1 · An affine recurrence with index 0',r'<p>If u₀=4 and \(u_{n+1}=2u_n+3\), prove \(u_n=7\cdot2^n-3\), n≥0.</p>',r'<p>At n=0, 7−3=4=u₀. Assume uₖ=7·2ᵏ−3. The recurrence gives</p>\[u_{k+1}=2(7\cdot2^k-3)+3=7\cdot2^{k+1}-3.\]<p>Thus the formula holds for all integers n≥0 by induction. Starting at 1 would have left the supplied first term outside the conclusion.</p>',dict(kind='recurrence',formula='7*2**n-3',rule='2*u+3',start=0,initial=4)),
 ex('E-R2','2 · Prove a denominator sign before using a bound',r'<p>Let v₀=1/2 and \(v_{n+1}=(2v_n+3)/(v_n+4)\). Prove 0&lt;vₙ&lt;1 for all n≥0.</p>',r'<p>The base lies in (0,1). Suppose 0&lt;vₖ&lt;1. Then vₖ+4&gt;0 and 2vₖ+3&gt;0, so vₖ₊₁&gt;0. Also</p>\[1-v_{k+1}=\frac{1-v_k}{v_k+4}>0.\]<p>Both next inequalities hold and the next term is defined. By induction all terms belong to (0,1); neither endpoint is attained.</p>',dict(kind='interval',rule='(2*u+3)/(u+4)',lower=0,upper=1,initial='1/2',start=0)),
 ex('E-R3','3 · Carry two consecutive cases',r'<p>Given w₀=1, w₁=4 and \(w_{n+2}=4w_{n+1}-3w_n\), prove \(w_n=(3^{n+1}-1)/2\).</p>',r'<p>The formula gives 1 at n=0 and 4 at n=1. Assume it holds at k and k+1. Then</p>\[w_{k+2}=\frac{4(3^{k+2}-1)-3(3^{k+1}-1)}2=\frac{3^{k+3}-1}2.\]<p>This proves the next case while retaining the k+1 case. Induction on the pair of consecutive statements establishes the formula for all n≥0.</p>',dict(kind='second_order',formula='(3**(n+1)-1)/2',a=4,b=-3,initial=[1,4])),
 ex('E-R4','4 · A square-root map preserves an interval',r'<p>If u₀=2 and \(u_{n+1}=\sqrt{6+u_n}\), prove 2≤uₙ&lt;3 for all n≥0.</p>',r'<p>The base satisfies both bounds. Suppose 2≤uₖ&lt;3. Then 8≤6+uₖ&lt;9. The radicand is positive, and the non-negative square-root function is increasing, so</p>\[2<\sqrt8\le u_{k+1}<3.\]<p>In particular 2≤uₖ₊₁&lt;3. Induction proves the claimed interval for every n≥0; strictness of the upper bound is preserved.</p>',dict(kind='sqrt_interval',offset=6,lower=2,upper=3,initial=2))
 )),
lesson('matrices','Induction for matrix powers',
 'Multiply the assumed matrix formula in the correct order and verify every entry.',
 'Prove matrix-power identities, including parity patterns and nilpotent corrections.',
 r'<p>Review <a href="/courses/maths4u-9231-fp1/topics/fp1_matrices_operations">matrix multiplication</a> and <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">the induction framework</a>. Use the identity matrix I, with A⁰=I for any square A.</p>',
 r'''<h3>An entrywise claim about a whole matrix</h3><p>To prove Aⁿ=F(n), check every entry at the base. Assuming Aᵏ=F(k), calculate \(A^{k+1}=F(k)A\). It is also valid to multiply A on the left, but write the resulting order consistently. General matrices do not commute; identities for (AB)ⁿ require their own justification.</p>
 <h3>Use a small algebraic structure</h3><p>If N²=0, multiplication shows \((I+cN)^n=I+ncN\). The proof uses N²=0 at the transition; checking a few powers only suggests the formula. If N³=0, a second correction survives:</p>
 \[(I+N)^n=I+nN+\frac{n(n-1)}2N^2.\]
 <p>Multiplying by I+N updates the N² coefficient from k(k−1)/2 to k(k+1)/2, while the N³ term vanishes. Establish the nilpotent identity for the actual matrix first.</p>
 <h3>Parity and special parameter values</h3><p>When A²=cI, prove the even and odd powers together: \(A^{2n}=c^nI\) and \(A^{2n+1}=c^nA\). A step in n multiplies by A². Do not use an even-only base and then conclude every exponent has the even formula. Parameter-dependent formulae must remain defined at exceptional values; check those separately if your derivation divides by a parameter.</p>''',
 r'<ol><li>Specify n≥0 or the true starting exponent.</li><li>Check the identity matrix or first power entry by entry.</li><li>Assume the complete matrix formula.</li><li>Multiply in the stated order and simplify every entry.</li><li>Identify the exact next formula and conclude on its stated domain.</li></ol>',
 ['A⁰ is the identity matrix, not the zero matrix.','Do not replace matrix multiplication with entrywise multiplication.','An even-power formula does not automatically cover odd powers.','A proof for a generic parameter must not discard a zero-parameter case.'],
 examples(
 ex('E-M1','1 · A non-triangular matrix with a simple correction',r'<p>For \(A=\begin{pmatrix}3&-2\\2&-1\end{pmatrix}\), prove \(A^n=I+2nN\), where \(N=\begin{pmatrix}1&-1\\1&-1\end{pmatrix}\), n≥0.</p>',r'<p>Direct multiplication gives N²=0 and A=I+2N. The base n=0 is A⁰=I. Assuming Aᵏ=I+2kN,</p>\[A^{k+1}=(I+2kN)(I+2N)=I+2(k+1)N+4kN^2=I+2(k+1)N.\]<p>Thus the complete matrix identity holds for every n≥0 by induction, even though A itself is not triangular.</p>',dict(kind='matrix',matrix=[[3,-2],[2,-1]],formula=[['1+2*n','-2*n'],['2*n','1-2*n']],start=0)),
 ex('E-M2','2 · Opposite signs on a diagonal',r'<p>Prove \(\operatorname{diag}(2,-3)^n=\operatorname{diag}(2^n,(-3)^n)\), n≥0.</p>',r'<p>At n=0 both matrices are I. Assume the kth formula. Multiplying by diag(2,−3) multiplies the first diagonal entry by 2 and the second by −3; both off-diagonal entries remain zero. The result is diag(2ᵏ⁺¹,(−3)ᵏ⁺¹), proving P(k+1). Hence induction establishes all non-negative powers, including the alternating sign.</p>',dict(kind='matrix',matrix=[[2,0],[0,-3]],formula=[['2**n','0'],['0','(-3)**n']],start=0)),
 ex('E-M3','3 · Prove both parity cases',r'<p>For \(C=\begin{pmatrix}0&1\\1&0\end{pmatrix}\), prove C²ⁿ=I and C²ⁿ⁺¹=C for n≥0.</p>',r'<p>Compute C²=I. At n=0 the paired claims are C⁰=I and C¹=C. Assume both claims for k. Multiplying each by C²=I yields C²ᵏ⁺²=I and C²ᵏ⁺³=C. These are exactly the pair at k+1. Therefore both claims hold for all n≥0 by induction.</p>',dict(kind='matrix_parity',matrix=[[0,1],[1,0]],scalar=1)),
 ex('E-M4','4 · A quadratic correction in a 3 by 3 matrix',r'<p>Let \(J=\begin{pmatrix}0&2&0\\0&0&1\\0&0&0\end{pmatrix}\). Prove \((I+J)^n=I+nJ+n(n-1)J^2/2\), n≥0.</p>',r'<p>J² has only its top-right entry non-zero, equal to 2, and J³=0. The formula is I at n=0. Assuming it for k, multiplication by I+J gives</p>\[I+(k+1)J+\left(k+\frac{k(k-1)}2\right)J^2=I+(k+1)J+\frac{k(k+1)}2J^2.\]<p>The discarded term is a multiple of J³=0. This proves the k+1 formula and completes induction for all n≥0.</p>',dict(kind='matrix',matrix=[[1,2,0],[0,1,1],[0,0,1]],formula=[['1','2*n','n*(n-1)'],['0','1','n'],['0','0','1']],start=0))
 )),
lesson('divisibility','Divisibility and a complete inductive argument',
 'Carry an integer multiple or a residue forward, and conclude on the correct index set.',
 'Prove divisibility statements by an explicit integer bridge and handle restricted indices precisely.',
 r'<p>Complete <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">the induction framework</a>. Review factors, integer multiples, residues and products of consecutive integers.</p>',
 r'''<h3>Keep the integer witness visible</h3><p>To prove d divides f(n), with a fixed non-zero integer d, assume f(k)=dq for an integer q. Try to express</p>
 \[f(k+1)=a f(k)+dR(k),\]
 <p>where a is an integer and R(k) is an integer for every admissible k. The next value is then d(aq+R(k)), an integer multiple of d. The base case must also be divisible by d. Simply saying that an expression looks even or divisible does not establish an integer witness.</p>
 <h3>Two useful transitions</h3><p>For polynomial f, factor the difference f(k+1)−f(k). For exponential f, a multiple a f(k) may cancel a difficult exponential term. If a remaining product needs an extra factor, justify it: consecutive integers have an even product, and a residue check may establish a factor of 3.</p>
 <h3>Congruences state the same integer fact</h3><p>The statement f(n)≡r(n) (mod d) means d divides f(n)−r(n). It may be easier to prove this stronger residue statement first, then identify every n for which the residue is zero. A statement for odd indices requires an odd-index transition, or a re-indexed variable; do not silently conclude it for even integers too.</p>
 <p>For a complete proof, record the allowed starting integer, use the hypothesis explicitly, justify the remaining integer multiple, and give the exact final domain. Short checks below practise those ingredients; a correct fragment is not certification of a complete written proof.</p>''',
 r'<ol><li>State the divisor, function and integer domain.</li><li>Check the actual first case.</li><li>Write the hypothesis as an integer multiple or congruence.</li><li>Produce a transition with an explicitly divisible remainder.</li><li>Conclude with the base, implication and precise set of indices.</li></ol>',
 ['A rational quotient is not necessarily an integer.','Changing a residue without justification can invalidate the step.','For an odd-index claim the next admissible index is k+2.','A valid transition cannot replace a missing base case.'],
 examples(
 ex('E-V1','1 · Use a multiple of the previous expression',r'<p>Prove 4 divides 5ⁿ−1 for every integer n≥0.</p>',r'<p>At n=0 the expression is 0, a multiple of 4. Assume 5ᵏ−1=4q with integer q. Then</p>\[5^{k+1}-1=5(5^k-1)+4=4(5q+1).\]<p>The bracket is an integer, proving the next case. By induction the claim holds for every integer n≥0.</p>',dict(kind='divisibility',function='5**n-1',divisor=4,multiplier=5,remainder='4',start=0)),
 ex('E-V2','2 · Factor a polynomial difference',r'<p>Prove 6 divides (n+1)(n+2)(n+3) for every integer n≥0.</p>',r'<p>For n=0 the product is 6. Put f(n)=(n+1)(n+2)(n+3) and assume f(k)=6q. Then</p>\[f(k+1)-f(k)=3(k+2)(k+3).\]<p>One of k+2 and k+3 is even, so (k+2)(k+3)/2 is an integer. Thus f(k+1)=6(q+(k+2)(k+3)/2), an integer multiple of 6. The base and implication prove the result for all n≥0.</p>',dict(kind='divisibility',function='(n+1)*(n+2)*(n+3)',divisor=6,multiplier=1,remainder='3*(n+2)*(n+3)',start=0)),
 ex('E-V3','3 · Match one of two exponential growth factors',r'<p>Prove 7 divides 9ⁿ+6·2ⁿ for all integers n≥0.</p>',r'<p>The n=0 value is 7. Put f(n)=9ⁿ+6·2ⁿ and assume f(k)=7q. Then</p>\[f(k+1)=2f(k)+7\cdot9^k=7(2q+9^k).\]<p>Because q and 9ᵏ are integers, this establishes P(k+1). The base and implication prove divisibility by 7 for every n≥0.</p>',dict(kind='divisibility',function='9**n+6*2**n',divisor=7,multiplier=2,remainder='7*9**n',start=0)),
 ex('E-V4','4 · An odd-index conclusion uses a step of two',r'<p>Prove 8 divides n²−1 for every positive odd integer n.</p>',r'<p>The base n=1 gives 0. Assume k is a positive odd integer and k²−1=8q. The next odd integer is k+2, and</p>\[(k+2)^2-1=(k^2-1)+4(k+1)=8\left(q+\frac{k+1}2\right).\]<p>Since k is odd, (k+1)/2 is an integer. The base and step of two cover every positive odd integer. The conclusion does not include even integers: n=2 gives 3.</p>',dict(kind='odd_divisibility',function='n**2-1',divisor=8,start=1))
 ))
]
